/**
 * Spanish and French for the mission knowledge base that the backend serves in English
 * (data/indicators.json and data/hazards.json): indicator names, why it matters, how to measure,
 * actions, when to report, threshold notes and the evidence cards (title, summary, limitations).
 *
 * Same format as ApolloCare's catalog (Spanish -> { en, fr }). "en" is the backend text exactly as
 * served, so the translator recognizes it on screen and swaps it for the active language.
 * If a text in the data files changes, it simply stays in English until this file is updated.
 * Paper titles and bibliographic citations are left in their original language on purpose.
 * Translation by the team; pending review by a health professional, like the source texts.
 */
export const CONTENT_STRINGS: Record<string, { en: string; fr: string }> = {
  "Duración del sueño": { en: "Sleep duration", fr: "Durée du sommeil" },
  "Estudios con astronautas de las misiones del transbordador y de la Mir reportan menos horas de sueño en vuelo. Dormir poco va de la mano con fatiga y menor rendimiento, así que tu propia tendencia importa más que una sola noche.": { en: "Astronaut studies from Shuttle and Mir missions report shorter sleep in flight. Short sleep goes together with fatigue and slower performance, so your own trend matters more than one night.", fr: "Les études menées auprès d’astronautes des missions de la navette et de Mir rapportent un sommeil plus court en vol. Le manque de sommeil va de pair avec la fatigue et une baisse des performances : votre propre tendance compte donc plus qu’une seule nuit." },
  "Anota cada mañana las horas que dormiste, o impórtalas de un dispositivo de muñeca si la tripulación tiene uno.": { en: "Log the hours you slept each morning, or import them from a wrist device if the crew has one.", fr: "Notez chaque matin vos heures de sommeil, ou importez-les depuis un appareil au poignet si l’équipage en dispose." },
  "Protege esta noche un horario fijo para dormir.": { en: "Protect a fixed sleep window tonight.", fr: "Préservez ce soir une plage de sommeil fixe." },
  "Anótalo y vuelve a revisarlo mañana.": { en: "Note it and check again tomorrow.", fr: "Notez-le et vérifiez à nouveau demain." },
  "Mantén tu horario de sueño fijo y en silencio.": { en: "Keep your sleep window fixed and quiet.", fr: "Gardez une plage de sommeil fixe et au calme." },
  "Avisa hoy al oficial médico de la tripulación.": { en: "Tell the crew medical officer today.", fr: "Prévenez aujourd’hui le médecin de bord." },
  "Pide orientación al médico de vuelo (flight surgeon).": { en: "Ask the flight surgeon for guidance.", fr: "Demandez conseil au médecin de vol (flight surgeon)." },
  "Cualquier resultado rojo, o cualquier amarillo que siga empeorando durante varios días.": { en: "Any red result, or any yellow that keeps getting worse for several days.", fr: "Tout résultat rouge, ou tout résultat jaune qui continue de s’aggraver pendant plusieurs jours." },
  "Evalúa el patrón habitual, no una sola noche (la duración de la ventana es una decisión de diseño del equipo). Consenso terrestre para adultos sanos. Los astronautas de la ISS promediaron 6.5 h en vuelo (Jones 2022), así que el amarillo será frecuente: mantén visible la tendencia personal.": { en: "Evaluate on the usual pattern, not on one night (the window length is a team design choice). Terrestrial consensus for healthy adults. ISS astronauts averaged 6.5 h in flight (Jones 2022), so yellow will be common: keep the personal trend visible.", fr: "À évaluer sur l’habitude, pas sur une seule nuit (la durée de la fenêtre est un choix de conception de l’équipe). Consensus terrestre pour les adultes en bonne santé. Les astronautes de l’ISS ont dormi en moyenne 6,5 h en vol (Jones 2022) : le jaune sera donc fréquent, gardez la tendance personnelle visible." },
  "Adultos de 18 a 60 años: 7 horas o más por noche de forma regular.": { en: "Adults 18-60: 7 or more hours per night on a regular basis.", fr: "Adultes de 18 à 60 ans : 7 heures ou plus par nuit de façon régulière." },
  "Seis horas o menos por noche no bastan para mantener la salud y la seguridad en adultos.": { en: "Six or fewer hours per night is inadequate to sustain health and safety in adults.", fr: "Six heures ou moins par nuit ne suffisent pas à préserver la santé et la sécurité chez l’adulte." },
  "Calidad del sueño": { en: "Sleep quality", fr: "Qualité du sommeil" },
  "Estudios pequeños con astronautas reportan cambios en la calidad y la continuidad del sueño en vuelo, pero no en la misma dirección para cada medida o misión.": { en: "Small astronaut studies report changes in sleep quality and continuity in flight, but not in the same direction for every measure or mission.", fr: "De petites études chez les astronautes rapportent des changements de la qualité et de la continuité du sommeil en vol, mais pas dans le même sens pour chaque mesure ou mission." },
  "Califica cada mañana qué tan descansado te sientes en una escala del 1 al 5 (escala definida por la app).": { en: "Rate how rested you feel each morning on a 1-5 scale (app-defined scale).", fr: "Évaluez chaque matin à quel point vous vous sentez reposé sur une échelle de 1 à 5 (échelle définie par l’app)." },
  "Anota la luz, el ruido y la temperatura de tu área de descanso.": { en: "Note light, noise and temperature in your sleep area.", fr: "Notez la lumière, le bruit et la température de votre zone de repos." },
  "Horario de sueño": { en: "Sleep timing", fr: "Horaires de sommeil" },
  "En los estudios de vuelo, el ritmo circadiano y la iluminación se relacionan con el sueño y el estado de alerta. Mantener un horario estable ayuda a interpretar bien tus datos de sueño.": { en: "Circadian timing and lighting are linked to sleep and alertness in flight studies. Keeping timing steady helps read your sleep data correctly.", fr: "Dans les études en vol, le rythme circadien et l’éclairage sont liés au sommeil et à la vigilance. Garder des horaires stables aide à bien interpréter vos données de sommeil." },
  "Anota la hora en que te dormiste y en que despertaste.": { en: "Log the time you went to sleep and woke up.", fr: "Notez l’heure du coucher et du réveil." },
  "Mantén las horas de dormir y despertar tan estables como lo permita la agenda.": { en: "Keep sleep and wake times as steady as the schedule allows.", fr: "Gardez des heures de coucher et de réveil aussi stables que le planning le permet." },
  "Cohesión de la tripulación y estado de ánimo": { en: "Crew cohesion and mood", fr: "Cohésion de l’équipage et humeur" },
  "El aislamiento y el confinamiento pueden afectar la convivencia de la tripulación. La evidencia directa en astronautas es limitada, así que la app sigue la tendencia de cada persona en lugar de suponer una caída en una fecha fija.": { en: "Isolation and confinement can affect how crew members get along. Direct astronaut evidence is limited, so the app follows each person's own trend instead of assuming a dip at a fixed date.", fr: "L’isolement et le confinement peuvent affecter les relations au sein de l’équipage. Les preuves directes chez les astronautes sont limitées : l’app suit donc la tendance de chaque personne au lieu de supposer une baisse à une date fixe." },
  "Responde un breve registro diario sobre estado de ánimo, relación con el equipo y apoyo (escala definida por la app).": { en: "Answer a short daily check-in about mood, team relations and support (app-defined scale).", fr: "Répondez à un court bilan quotidien sur l’humeur, les relations d’équipe et le soutien (échelle définie par l’app)." },
  "Habla con un integrante de la tripulación de tu confianza.": { en: "Talk with a crew member you trust.", fr: "Parlez à un membre de l’équipage en qui vous avez confiance." },
  "Anota qué cambió en la agenda o en la carga de trabajo.": { en: "Note what changed in the schedule or workload.", fr: "Notez ce qui a changé dans le planning ou la charge de travail." },
  "Tiempo de reacción": { en: "Reaction time", fr: "Temps de réaction" },
  "La NASA sigue el estado de alerta y el rendimiento con pruebas de reacción cortas y repetidas, comparadas con tu propia línea base. Las reacciones más lentas pueden aparecer antes de que te sientas cansado.": { en: "Short repeated reaction tests compared with your own baseline are how NASA tracks alertness and performance. Slower reactions can show up before you feel tired.", fr: "La NASA suit la vigilance et les performances à l’aide de tests de réaction courts et répétés, comparés à votre propre niveau de référence. Des réactions plus lentes peuvent apparaître avant que vous ne vous sentiez fatigué." },
  "Haz la autoprueba de reacción de 3 minutos (tipo PVT-B) a la misma hora del día. Guarda el tiempo de reacción promedio, el número de lapsos (TR >= 355 ms) y las salidas en falso (TR < 130 ms).": { en: "Do the 3-minute reaction self-test (PVT-B style) at the same time of day. Save the mean reaction time, the number of lapses (RT >= 355 ms) and false starts (RT < 130 ms).", fr: "Faites l’autotest de réaction de 3 minutes (type PVT-B) à la même heure de la journée. Enregistrez le temps de réaction moyen, le nombre de défaillances (TR >= 355 ms) et les faux départs (TR < 130 ms)." },
  "Revisa tu tendencia de sueño: ambas suelen moverse juntas.": { en: "Check your sleep trend: the two often move together.", fr: "Vérifiez votre tendance de sommeil : les deux évoluent souvent ensemble." },
  "Evita realizar solo tareas críticas para la seguridad.": { en: "Avoid safety-critical tasks alone.", fr: "Évitez d’effectuer seul des tâches critiques pour la sécurité." },
  "Criterio demo del equipo: NO proviene de una fuente. Números redondos elegidos por el equipo para la demostración, aplicados al cambio de la mediana reciente respecto a la línea base de la persona.": { en: "Team demo criterion: NOT from a source. Round numbers chosen by the team for the demo, applied to the change of the recent median against the person's own baseline.", fr: "Critère de démo de l’équipe : NE provient PAS d’une source. Chiffres ronds choisis par l’équipe pour la démonstration, appliqués à l’écart de la médiane récente par rapport au niveau de référence de la personne." },
  "Tiempo de ejercicio": { en: "Exercise time", fr: "Temps d’exercice" },
  "El ejercicio es la contramedida usada de forma constante contra la atrofia muscular y la pérdida de fuerza en microgravedad. El informe de 2009 describe unas 2.5 horas al día, seis días a la semana, en la ISS (incluyendo preparación e higiene).": { en: "Exercise is the countermeasure used consistently against muscle atrophy and strength loss in microgravity. The 2009 report describes about 2.5 hours per day on six days a week on the ISS (setup and hygiene included).", fr: "L’exercice est la contre-mesure utilisée de façon constante contre l’atrophie musculaire et la perte de force en microgravité. Le rapport de 2009 décrit environ 2,5 heures par jour, six jours par semaine, sur l’ISS (préparation et hygiène comprises)." },
  "Anota cada día los minutos de ejercicio de resistencia y aeróbico.": { en: "Log minutes of resistance and aerobic exercise each day.", fr: "Notez chaque jour les minutes d’exercice de résistance et d’aérobie." },
  "Protege tu bloque de ejercicio en el plan del día.": { en: "Protect your exercise slot in the day plan.", fr: "Préservez votre créneau d’exercice dans le plan de la journée." },
  "Informa al oficial médico de la tripulación sobre las sesiones que no hiciste.": { en: "Tell the crew medical officer about missed sessions.", fr: "Informez le médecin de bord des séances manquées." },
  "Fuerza muscular": { en: "Muscle strength", fr: "Force musculaire" },
  "La microgravedad se asocia con atrofia muscular y menor fuerza y resistencia. El capítulo no da una estimación cuantitativa de pérdida muscular, así que solo tiene sentido el cambio respecto a tu propia línea base.": { en: "Microgravity is associated with muscle atrophy and lower strength and endurance. The chapter gives no quantitative muscle-loss estimate, so only the change from your own baseline is meaningful.", fr: "La microgravité est associée à une atrophie musculaire et à une baisse de la force et de l’endurance. Le chapitre ne donne aucune estimation chiffrée de la perte musculaire : seul l’écart par rapport à votre propre niveau de référence a du sens." },
  "Demo: valor simulado. Un protocolo real repetiría la misma prueba sencilla de fuerza en un horario semanal fijo.": { en: "Demo: simulated value. A real protocol would repeat the same simple strength check on a fixed weekly schedule.", fr: "Démo : valeur simulée. Un vrai protocole répéterait le même test de force simple selon un calendrier hebdomadaire fixe." },
  "Compárala con tu propia línea base en la gráfica de tendencia.": { en: "Compare with your own baseline in the trend chart.", fr: "Comparez avec votre propre niveau de référence dans le graphique de tendance." },
  "Calcio (sangre)": { en: "Calcium (blood)", fr: "Calcium (sang)" },
  "El calcio forma parte del panel metabólico que la NASA midió en la tripulación antes y después del vuelo (LSDS-8).": { en: "Calcium is part of the metabolic panel NASA measured in crew before and after flight (LSDS-8).", fr: "Le calcium fait partie du bilan métabolique que la NASA a mesuré chez l’équipage avant et après le vol (LSDS-8)." },
  "Valor de laboratorio de un análisis de sangre; el tripulante no puede medirlo por sí solo.": { en: "Lab value from a blood panel; not measurable by the crew member alone.", fr: "Valeur de laboratoire issue d’une prise de sang ; le membre d’équipage ne peut pas la mesurer seul." },
  "Anota el valor y la fecha.": { en: "Note the value and the date.", fr: "Notez la valeur et la date." },
  "Rango de laboratorio más frecuente por sexo en LSDS-8 (sin las filas previas al vuelo C003). Un rango de laboratorio no es un diagnóstico.": { en: "Most frequent lab range per sex in LSDS-8 (C003 pre-flight rows excluded). A lab range is not a diagnosis.", fr: "Plage de laboratoire la plus fréquente par sexe dans LSDS-8 (lignes pré-vol C003 exclues). Une plage de laboratoire n’est pas un diagnostic." },
  "Frecuencia cardíaca en reposo": { en: "Resting heart rate", fr: "Fréquence cardiaque au repos" },
  "El pulso es una señal rápida de todo el cuerpo. Una frecuencia en reposo que se aleja de tu línea base, sobre todo junto con fiebre, merece atención.": { en: "Pulse is a quick whole-body signal. A resting rate that moves away from your own baseline, especially together with fever, deserves attention.", fr: "Le pouls est un signal rapide de l’ensemble du corps. Une fréquence au repos qui s’éloigne de votre niveau de référence, surtout avec de la fièvre, mérite attention." },
  "Pulso por cámara (rPPG) o conteo manual en reposo. Compáralo con un oxímetro de pulso o un conteo manual antes de confiar en la cámara.": { en: "Camera pulse (rPPG) or manual count while resting. Compare with a pulse oximeter or a manual count before trusting the camera.", fr: "Pouls par caméra (rPPG) ou comptage manuel au repos. Comparez avec un oxymètre de pouls ou un comptage manuel avant de vous fier à la caméra." },
  "Descansa 5 minutos y vuelve a medir.": { en: "Rest 5 minutes and measure again.", fr: "Reposez-vous 5 minutes et mesurez à nouveau." },
  "En reposo, tranquilo y despierto. No hay un nivel rojo con fuente para la frecuencia cardíaca por sí sola: escala junto con otros signos (por ejemplo, fiebre) según las reglas médicas de la tripulación. Los atletas pueden estar por debajo de 60.": { en: "Resting, calm, awake. There is no sourced red level for heart rate alone: escalate with other signs (for example fever) according to the crew medical rules. Athletes can sit below 60.", fr: "Au repos, calme, éveillé. Il n’existe pas de niveau rouge sourcé pour la fréquence cardiaque seule : alertez en tenant compte d’autres signes (par exemple la fièvre) selon les règles médicales de l’équipage. Les athlètes peuvent être en dessous de 60." },
  "Habla con un profesional si tu frecuencia en reposo suele estar por encima de 100.": { en: "Talk to a professional if resting rate is regularly above 100.", fr: "Consultez un professionnel si votre fréquence au repos dépasse régulièrement 100." },
  "Aplica si no eres un atleta entrenado: habla con un profesional si suele estar por debajo de 60.": { en: "Applies if not a trained athlete: talk to a professional if often below 60.", fr: "Valable si vous n’êtes pas un athlète entraîné : consultez un professionnel si elle est souvent en dessous de 60." },
  "Presión arterial (sistólica)": { en: "Blood pressure (systolic)", fr: "Pression artérielle (systolique)" },
  "La hipertensión figura entre las posibles preocupaciones cardiovasculares tardías de la radiación espacial, pero la evidencia de 2009 proviene de poblaciones que no son astronautas. Tómalo como un vacío de investigación, no como un efecto demostrado en vuelo.": { en: "Hypertension is listed among possible late cardiovascular concerns of space radiation, but the 2009 evidence comes from non-astronaut populations. Treat this as a research gap, not a proven in-flight effect.", fr: "L’hypertension figure parmi les effets cardiovasculaires tardifs possibles du rayonnement spatial, mais les données de 2009 proviennent de populations non astronautes. Considérez-le comme une lacune de la recherche, pas comme un effet démontré en vol." },
  "Medición con brazalete, sentado y en reposo, a la misma hora del día.": { en: "Cuff measurement, seated and rested, at the same time of day.", fr: "Mesure au brassard, assis et au repos, à la même heure de la journée." },
  "Descansa y vuelve a medir.": { en: "Rest and measure again.", fr: "Reposez-vous et mesurez à nouveau." },
  "Temperatura corporal": { en: "Body temperature", fr: "Température corporelle" },
  "La fiebre es una señal sencilla de infección o inflamación. La ayuda médica está lejos, así que conviene reportar la fiebre pronto.": { en: "Fever is a simple sign of infection or inflammation. Medical help is far away, so a fever is worth reporting early.", fr: "La fièvre est un signe simple d’infection ou d’inflammation. L’aide médicale est loin : il vaut donc la peine de signaler une fièvre tôt." },
  "Termómetro oral a la misma hora del día (los umbrales son para lecturas orales). Anota el sitio si usas otro.": { en: "Oral thermometer at the same time of day (the thresholds are for oral readings). Note the site if you use another.", fr: "Thermomètre buccal à la même heure de la journée (les seuils concernent les mesures buccales). Notez le site si vous en utilisez un autre." },
  "Vuelve a medir en una hora.": { en: "Measure again in an hour.", fr: "Mesurez à nouveau dans une heure." },
  "Toma líquidos y descansa.": { en: "Drink fluids and rest.", fr: "Buvez et reposez-vous." },
  "Los valores se refieren a lecturas ORALES. Las de la frente salen unos 0.6 °C más bajas; las rectales y de oído, unos 0.6 °C más altas. Registra el sitio de medición.": { en: "Values refer to ORAL readings. Forehead readings run about 0.6 C lower, rectal and ear about 0.6 C higher. Record the measurement site.", fr: "Les valeurs concernent des mesures BUCCALES. Les mesures frontales sont environ 0,6 °C plus basses ; les mesures rectales et auriculaires environ 0,6 °C plus hautes. Notez le site de mesure." },
  "Fiebre en adultos: 100.4 °F (38 °C), medición oral.": { en: "Adult fever: 100.4 F (38 C), oral measurement.", fr: "Fièvre chez l’adulte : 100,4 °F (38 °C), mesure buccale." },
  "Por encima de 103 °F (39.4 °C): llama a un profesional de la salud.": { en: "Above 103 F (39.4 C): call a healthcare provider.", fr: "Au-dessus de 103 °F (39,4 °C) : contactez un professionnel de santé." },
  "Glucosa en sangre": { en: "Blood glucose", fr: "Glycémie" },
  "La regulación de la glucosa forma parte del panorama metabólico, pero el capítulo de 2009 no da resultados de glucosa en astronautas. En LSDS-8, los valores muy bajos en R+45 probablemente son artefactos de la muestra (procesamiento tardío), no un hallazgo.": { en: "Glucose regulation is part of the metabolic picture, but the 2009 chapter gives no astronaut glucose result. In LSDS-8, the very low values at R+45 are probably sample artifacts (late processing), not a finding.", fr: "La régulation du glucose fait partie du tableau métabolique, mais le chapitre de 2009 ne donne aucun résultat de glycémie chez les astronautes. Dans LSDS-8, les valeurs très basses à R+45 sont probablement des artefacts d’échantillon (traitement tardif), pas un résultat." },
  "Creatinina (sangre)": { en: "Creatinine (blood)", fr: "Créatinine (sang)" },
  "La creatinina es un marcador relacionado con el riñón dentro del panel metabólico que la NASA midió antes y después del vuelo (LSDS-8).": { en: "Creatinine is a kidney-related marker in the metabolic panel NASA measured before and after flight (LSDS-8).", fr: "La créatinine est un marqueur lié aux reins dans le bilan métabolique que la NASA a mesuré avant et après le vol (LSDS-8)." },
  "Destellos de luz": { en: "Light flashes", fr: "Éclairs lumineux" },
  "Desde Apolo, los astronautas han reportado breves destellos de luz (fosfenos), estudiados en Skylab, la Mir y la ISS. Son subjetivos y por sí solos no indican lesión cerebral.": { en: "Astronauts have reported brief light flashes (phosphenes) since Apollo, and they were studied on Skylab, Mir and the ISS. They are subjective and do not by themselves show brain injury.", fr: "Depuis Apollo, des astronautes rapportent de brefs éclairs lumineux (phosphènes), étudiés sur Skylab, Mir et l’ISS. Ils sont subjectifs et n’indiquent pas à eux seuls une lésion cérébrale." },
  "Cuenta cuántos destellos notaste hoy y anota el contexto.": { en: "Count how many flashes you noticed today and note the context.", fr: "Comptez le nombre d’éclairs remarqués aujourd’hui et notez le contexte." },
  "Anota la hora y dónde estabas.": { en: "Log the time and where you were.", fr: "Notez l’heure et l’endroit où vous étiez." },
  "Dosis de radiación (modelada)": { en: "Radiation dose (modeled)", fr: "Dose de rayonnement (modélisée)" },
  "Los eventos de partículas solares son un posible peligro de radiación aguda para las tripulaciones. La evaluación de 2009 se basa en modelos: no reporta casos confirmados de síndrome de radiación aguda en astronautas.": { en: "Solar particle events are a potential acute radiation hazard for crews. The 2009 assessment is model-based: it does not report confirmed acute radiation syndrome in astronauts.", fr: "Les événements de particules solaires sont un danger potentiel de rayonnement aigu pour les équipages. L’évaluation de 2009 repose sur des modèles : elle ne rapporte aucun syndrome d’irradiation aiguë confirmé chez les astronautes." },
  "Del registro del entorno o de la simulación; el tripulante no la mide.": { en: "From the environment feed or the simulation; not measured by the crew member.", fr: "Issue du flux environnemental ou de la simulation ; non mesurée par le membre d’équipage." },
  "Sigue el plan de refugio contra radiación del hábitat.": { en: "Follow the radiation shelter plan for the habitat.", fr: "Suivez le plan d’abri contre les radiations de l’habitat." },
  "Ve al área de refugio según el procedimiento de la misión.": { en: "Go to the shelter area per mission procedure.", fr: "Rendez-vous dans la zone d’abri selon la procédure de mission." },
  "Intercambios cromosómicos": { en: "Chromosome exchanges", fr: "Échanges chromosomiques" },
  "En 24 astronautas, las muestras de sangre tomadas antes y después del vuelo mostraron más intercambios cromosómicos. Es un marcador biológico, no un diagnóstico de cáncer.": { en: "In 24 astronauts, blood samples taken before and after flight showed more chromosome exchanges. This is a biological marker, not a cancer diagnosis.", fr: "Chez 24 astronautes, des prises de sang avant et après le vol ont montré davantage d’échanges chromosomiques. C’est un marqueur biologique, pas un diagnostic de cancer." },
  "La app no lo mide. Análisis de laboratorio de muestras de sangre.": { en: "Not measured by the app. Laboratory analysis of blood samples.", fr: "Non mesuré par l’app. Analyse de laboratoire d’échantillons sanguins." },
  "Función cerebral (riesgo por radiación)": { en: "Brain function (radiation risk)", fr: "Fonction cérébrale (risque lié au rayonnement)" },
  "El capítulo de 2009 no identificó efectos cerebrales relacionados con la radiación en astronautas y señaló que no era posible hacer proyecciones de riesgo confiables. La ausencia de evidencia no demuestra que no haya riesgo.": { en: "The 2009 chapter found no identified radiation-related brain effects in astronauts, and said reliable risk projections were not possible. Absence of evidence is not proof of no risk.", fr: "Le chapitre de 2009 n’a identifié aucun effet cérébral lié au rayonnement chez les astronautes et indiquait qu’aucune projection de risque fiable n’était possible. L’absence de preuve n’est pas la preuve de l’absence de risque." },
  "No se mide directamente. El tiempo de reacción y el sueño son las señales diarias prácticas.": { en: "Not measured directly. Reaction time and sleep are the practical daily signals.", fr: "Non mesurée directement. Le temps de réaction et le sommeil sont les signaux quotidiens pratiques." },
  "Síntomas por polvo lunar": { en: "Lunar dust symptoms", fr: "Symptômes liés à la poussière lunaire" },
  "Las tripulaciones del Apolo describieron que el polvo lunar irritaba los ojos, la garganta y la nariz. Los efectos de una exposición prolongada son inciertos.": { en: "Apollo crews described lunar dust irritating the eyes, throat and nose. Effects of long exposure are uncertain.", fr: "Les équipages d’Apollo ont décrit une poussière lunaire irritant les yeux, la gorge et le nez. Les effets d’une exposition prolongée sont incertains." },
  "Califica la irritación de ojos, garganta y nariz después de una EVA (escala definida por la app).": { en: "Rate eye, throat and nose irritation after EVA (app-defined scale).", fr: "Évaluez l’irritation des yeux, de la gorge et du nez après une EVA (échelle définie par l’app)." },
  "Limpia el traje y las botas antes de entrar al hábitat.": { en: "Clean suit and boots before entering the habitat.", fr: "Nettoyez la combinaison et les bottes avant d’entrer dans l’habitat." },
  "Eventos de contacto con polvo": { en: "Dust contact events", fr: "Contacts avec la poussière" },
  "El polvo puede entrar al hábitat en trajes y botas después de una EVA, al limpiar los trajes y al cambiar filtros. Son vías de exposición, no dosis medidas.": { en: "Dust can enter the habitat on suits and boots after EVA, during suit cleaning and when filters are changed. These are exposure pathways, not measured doses.", fr: "La poussière peut entrer dans l’habitat sur les combinaisons et les bottes après une EVA, lors du nettoyage des combinaisons et lors du changement des filtres. Ce sont des voies d’exposition, pas des doses mesurées." },
  "Anota las EVA, la limpieza de trajes y los cambios de filtro.": { en: "Log EVAs, suit-cleaning and filter-change tasks.", fr: "Notez les EVA, le nettoyage des combinaisons et les changements de filtres." },
  "Sigue el procedimiento de limpieza del traje y de ingreso.": { en: "Follow the suit-cleaning and ingress procedure.", fr: "Suivez la procédure de nettoyage de la combinaison et d’entrée." },
  "Accesibilidad del espacio de trabajo": { en: "Workspace accessibility", fr: "Accessibilité de l’espace de travail" },
  "La acumulación de objetos guardados puede bloquear rutas de paso, paneles y equipos, lo que afecta la eficiencia y el acceso de emergencia.": { en: "Accumulated stowage can block translation paths, panels and equipment, which matters for efficiency and emergency access.", fr: "L’accumulation d’objets rangés peut bloquer les voies de passage, les panneaux et l’équipement, ce qui compte pour l’efficacité et l’accès d’urgence." },
  "Califica el acceso a las rutas y al equipo de tu módulo.": { en: "Rate access to routes and equipment in your module.", fr: "Évaluez l’accès aux voies et à l’équipement de votre module." },
  "Despeja la ruta bloqueada o repórtala.": { en: "Clear the blocked route or report it.", fr: "Dégagez la voie bloquée ou signalez-la." },
  "Reporta de inmediato una ruta de emergencia bloqueada.": { en: "Report a blocked emergency route immediately.", fr: "Signalez immédiatement une voie d’urgence bloquée." },
  "Molestias por el traje": { en: "Suit discomfort", fr: "Inconfort de la combinaison" },
  "En pruebas en tierra, los participantes reportaron molestias con el traje que aumentaban al presurizarlo. Es evidencia indirecta: no se confirmó que los participantes fueran astronautas en vuelo.": { en: "In ground tests, participants reported suit discomfort that increased when pressurized. This is indirect evidence: participants were not confirmed as flight astronauts.", fr: "Lors d’essais au sol, des participants ont signalé un inconfort de la combinaison qui augmentait sous pressurisation. Ce sont des preuves indirectes : il n’a pas été confirmé que les participants étaient des astronautes en vol." },
  "Califica las molestias por zona del cuerpo después de usar el traje.": { en: "Rate discomfort by body region after suit use.", fr: "Évaluez l’inconfort par zone du corps après l’utilisation de la combinaison." },
  "Reporta la zona y la actividad.": { en: "Report the area and the activity.", fr: "Signalez la zone et l’activité." },
  "Vacío de evidencia específica en astronautas: enfermedad cardiovascular relacionada con la radiación": { en: "Astronaut-specific evidence gap: radiation-related cardiovascular disease", fr: "Lacune de preuves propres aux astronautes : maladie cardiovasculaire liée au rayonnement" },
  "El Evidence Book de 2009 describe la enfermedad cardiovascular como un posible efecto tardío de la exposición a la radiación espacial. Sin embargo, la evidencia humana que revisa proviene sobre todo de pacientes con cáncer, sobrevivientes de bombas atómicas y trabajadores expuestos a radiación. Estas poblaciones no son astronautas y quedan fuera de la evidencia central de ASTRA HEALTH, que solo incluye astronautas. El capítulo no demuestra enfermedad cardiovascular inducida por radiación en astronautas.": { en: "The 2009 Evidence Book describes cardiovascular disease as a potential late effect of space-radiation exposure. However, the human evidence it reviews comes mainly from cancer patients, atomic-bomb survivors, and radiation-exposed workers. These populations are not astronauts and are excluded from ASTRA HEALTH's astronaut-only core evidence. The chapter does not establish radiation-induced cardiovascular disease in astronauts.", fr: "L’Evidence Book de 2009 décrit la maladie cardiovasculaire comme un effet tardif possible de l’exposition au rayonnement spatial. Cependant, les données humaines examinées proviennent surtout de patients atteints de cancer, de survivants des bombes atomiques et de travailleurs exposés aux rayonnements. Ces populations ne sont pas des astronautes et sont exclues du socle de preuves d’ASTRA HEALTH, limité aux astronautes. Le chapitre n’établit pas de maladie cardiovasculaire radio-induite chez les astronautes." },
  "No traslades directamente a los astronautas las estimaciones de riesgo de pacientes, sobrevivientes de bombas atómicas o trabajadores expuestos a radiación.": { en: "Do not transfer risk estimates from patients, atomic-bomb survivors, or radiation workers directly to astronauts.", fr: "Ne transposez pas directement aux astronautes les estimations de risque issues de patients, de survivants des bombes atomiques ou de travailleurs exposés aux rayonnements." },
  "La fuente se publicó en 2009 y no refleja el estado actual de la evidencia.": { en: "The source was published in 2009 and does not establish the current state of evidence.", fr: "La source a été publiée en 2009 et ne reflète pas l’état actuel des connaissances." },
  "Atrofia del músculo esquelético y pérdida de fuerza asociadas a la microgravedad": { en: "Microgravity-associated skeletal muscle atrophy and strength loss", fr: "Atrophie du muscle squelettique et perte de force associées à la microgravité" },
  "El Evidence Book identifica la atrofia del músculo esquelético y la menor fuerza y resistencia muscular como consecuencias de la exposición a la microgravedad. Señala que el ejercicio físico era la contramedida usada de forma constante en el programa de vuelos espaciales tripulados de EE. UU. en ese momento. El capítulo describe los horarios de ejercicio de la tripulación de la ISS, pero se centra en la carga de tiempo operativo del ejercicio y no cuantifica los cambios musculares individuales.": { en: "The Evidence Book identifies skeletal muscle atrophy and reduced muscle strength and endurance as consequences of microgravity exposure. It states that physical exercise was the countermeasure consistently used in the U.S. human spaceflight program at the time. The chapter describes ISS crew exercise schedules, but this particular chapter focuses on the operational time burden of exercise rather than quantifying individual muscle changes.", fr: "L’Evidence Book identifie l’atrophie du muscle squelettique et la baisse de la force et de l’endurance musculaires comme des conséquences de l’exposition à la microgravité. Il indique que l’exercice physique était alors la contre-mesure utilisée de façon constante dans le programme de vols spatiaux habités des États-Unis. Le chapitre décrit les horaires d’exercice de l’équipage de l’ISS, mais il porte sur la charge de temps opérationnelle de l’exercice plutôt que sur la quantification des changements musculaires individuels." },
  "No deduzcas de este capítulo un porcentaje ni una tasa de pérdida muscular.": { en: "Do not infer a percentage or rate of muscle loss from this chapter.", fr: "Ne déduisez de ce chapitre ni pourcentage ni taux de perte musculaire." },
  "La fuente describe el programa de EE. UU. en 2009; el equipo y las prescripciones pueden haber cambiado.": { en: "The source describes the U.S. program as of 2009; equipment and prescriptions may have changed.", fr: "La source décrit le programme américain en 2009 ; l’équipement et les prescriptions ont pu changer." },
  "Horario de ejercicio de la tripulación de la ISS y su competencia con las operaciones de la misión": { en: "ISS crew exercise schedule and competition with mission operations", fr: "Horaires d’exercice de l’équipage de l’ISS et concurrence avec les opérations de la mission" },
  "El capítulo reporta que, hasta 2008, los tripulantes estadounidenses de la ISS tenían programadas unas 2.5 horas de ejercicio aeróbico y de resistencia combinados seis de cada siete días. Ese tiempo incluía preparación, guardado del equipo e higiene personal. Los autores afirman que ninguna evidencia científica o anecdótica publicada mostraba que el tiempo de ejercicio programado hubiera afectado negativamente los objetivos de la misión, aunque competía por tiempo dentro de la jornada de la tripulación.": { en: "The chapter reports that, through 2008, U.S. ISS crew members were scheduled for approximately 2.5 hours of combined aerobic and resistance exercise on six of seven days. This time included setup, stowage, and personal hygiene. The authors state that no published scientific or anecdotal evidence showed that the scheduled exercise time had negatively affected mission objectives, although it competed for time within the crew duty day.", fr: "Le chapitre rapporte que, jusqu’en 2008, les membres américains de l’équipage de l’ISS avaient environ 2,5 heures d’exercice aérobie et de résistance combinés programmées six jours sur sept. Ce temps incluait la préparation, le rangement et l’hygiène personnelle. Les auteurs indiquent qu’aucune preuve scientifique ou anecdotique publiée ne montrait que le temps d’exercice programmé ait nui aux objectifs de la mission, même s’il empiétait sur le temps de la journée de travail de l’équipage." },
  "Horario histórico, no una prescripción actual de la ISS.": { en: "Historical schedule, not a current ISS prescription.", fr: "Horaires historiques, pas une prescription actuelle de l’ISS." },
  "El capítulo evalúa la carga de tiempo operativo, no la eficacia clínica comparada de los programas de ejercicio.": { en: "The chapter assesses operational time burden, not comparative clinical effectiveness of exercise regimens.", fr: "Le chapitre évalue la charge de temps opérationnelle, pas l’efficacité clinique comparée des programmes d’exercice." },
  "Vacío de evidencia específica en astronautas: resultados inmunológicos y metabólicos": { en: "Astronaut-specific evidence gap: immune and metabolic outcomes", fr: "Lacune de preuves propres aux astronautes : effets immunitaires et métaboliques" },
  "El capítulo de radiación del Evidence Book menciona una posible disfunción endocrina y del sistema inmunitario entre los efectos degenerativos preocupantes, pero la discusión no demuestra estos efectos en una cohorte de astronautas. El material mecanístico y epidemiológico citado no puede tratarse como evidencia directa en astronautas según la regla de población de ASTRA HEALTH. El capítulo revisado no aporta un conjunto de datos de astronautas sobre función inmunitaria, regulación de la glucosa o resultados metabólicos.": { en: "The Evidence Book's radiation chapter lists possible endocrine and immune-system dysfunction among degenerative outcomes of concern, but the discussion does not establish these outcomes in an astronaut cohort. The cited mechanistic and epidemiological material cannot be treated as direct astronaut evidence under ASTRA HEALTH's population rule. The reviewed chapter does not provide a dedicated astronaut dataset for immune function, glucose regulation, or metabolic outcomes.", fr: "Le chapitre sur les rayonnements de l’Evidence Book cite un dysfonctionnement possible des systèmes endocrinien et immunitaire parmi les effets dégénératifs préoccupants, mais la discussion n’établit pas ces effets dans une cohorte d’astronautes. Les données mécanistiques et épidémiologiques citées ne peuvent pas être considérées comme des preuves directes chez les astronautes selon la règle de population d’ASTRA HEALTH. Le chapitre examiné ne fournit pas de jeu de données d’astronautes sur la fonction immunitaire, la régulation du glucose ou les effets métaboliques." },
  "No trates los hallazgos en animales, cultivos celulares, pacientes o poblaciones terrestres como hallazgos en astronautas.": { en: "Do not treat animal, cell-culture, patient, or terrestrial-population findings as astronaut findings.", fr: "Ne considérez pas les résultats chez l’animal, en culture cellulaire, chez des patients ou dans des populations terrestres comme des résultats chez les astronautes." },
  "Esta tarjeta señala una limitación de la fuente, no prueba que esa evidencia no exista en otro lugar.": { en: "This card identifies a source limitation, not proof that no such evidence exists elsewhere.", fr: "Cette fiche signale une limite de la source, pas la preuve que de telles données n’existent pas ailleurs." },
  "Menor duración del sueño reportada durante los vuelos espaciales": { en: "Reduced sleep duration reported during spaceflight", fr: "Réduction de la durée du sommeil rapportée pendant les vols spatiaux" },
  "El capítulo de sueño revisa estudios de vuelos espaciales tripulados que reportan una menor duración del sueño en los astronautas durante las misiones. Estas observaciones son útiles para vigilar el sueño de la tripulación, pero los estudios citados en el informe de 2009 incluyen muestras pequeñas de astronautas y condiciones históricas de naves y misiones.": { en: "The sleep chapter reviews human spaceflight studies reporting reduced sleep duration among astronauts during missions. These observations are relevant to crew sleep monitoring, but the studies cited in the 2009 report involve relatively small astronaut samples and historical spacecraft and mission conditions.", fr: "Le chapitre sur le sommeil passe en revue des études de vols spatiaux habités rapportant une durée de sommeil réduite chez les astronautes pendant les missions. Ces observations sont utiles pour le suivi du sommeil de l’équipage, mais les études citées dans le rapport de 2009 portent sur de petits échantillons d’astronautes et sur des conditions historiques de vaisseaux et de missions." },
  "No combines resultados de distintos estudios sin revisar sus protocolos y tamaños de muestra.": { en: "Do not combine results across studies without checking their individual protocols and sample sizes.", fr: "Ne combinez pas les résultats de plusieurs études sans vérifier leurs protocoles et la taille de leurs échantillons." },
  "La fuente es histórica y no describe de forma completa las condiciones actuales de sueño en la ISS.": { en: "The source is historical and does not describe current ISS sleep conditions comprehensively.", fr: "La source est historique et ne décrit pas de façon complète les conditions de sommeil actuelles à bord de l’ISS." },
  "Cambios en la arquitectura y la calidad del sueño en microgravedad": { en: "Sleep architecture and quality changes in microgravity", fr: "Changements de l’architecture et de la qualité du sommeil en microgravité" },
  "El capítulo resume estudios fisiológicos del sueño realizados con grupos pequeños de astronautas durante misiones del transbordador y de la Mir. Reporta cambios en las características y la calidad del sueño en vuelo, pero los hallazgos deben mantenerse ligados al método de medición de cada estudio en lugar de generalizarse como un único efecto universal de la microgravedad.": { en: "The chapter summarizes physiological sleep studies conducted with small groups of astronauts during Shuttle and Mir missions. It reports changes in sleep characteristics and quality in flight, but the findings should remain linked to each study's specific measurement method rather than being generalized as a single universal microgravity effect.", fr: "Le chapitre résume des études physiologiques du sommeil menées sur de petits groupes d’astronautes lors de missions de la navette et de Mir. Il rapporte des changements des caractéristiques et de la qualité du sommeil en vol, mais les résultats doivent rester liés à la méthode de mesure de chaque étude plutôt que d’être généralisés comme un effet universel unique de la microgravité." },
  "Muestras pequeñas.": { en: "Small samples.", fr: "Petits échantillons." },
  "Los protocolos de medición varían según el estudio.": { en: "Measurement protocols vary by study.", fr: "Les protocoles de mesure varient selon les études." },
  "Los valores numéricos deben transcribirse del artículo original citado antes de usarlos de forma cuantitativa.": { en: "Numerical values must be transcribed from the original cited paper before quantitative use.", fr: "Les valeurs numériques doivent être reprises de l’article original cité avant tout usage quantitatif." },
  "Ritmo circadiano e iluminación durante los vuelos espaciales": { en: "Circadian timing and lighting during spaceflight", fr: "Rythme circadien et éclairage pendant les vols spatiaux" },
  "El capítulo analiza la desincronización circadiana y la iluminación como factores relevantes para el sueño y el estado de alerta de los astronautas. Resume estudios y observaciones pequeños en vuelo con tripulaciones del transbordador y de la Mir. La tarjeta registra la relación operativa descrita por la fuente; no prescribe una intervención de iluminación ni afirma un efecto cuantificado más allá de los estudios citados.": { en: "The chapter discusses circadian desynchronization and lighting as relevant to astronaut sleep and alertness. It summarizes small in-flight studies and observations involving Shuttle and Mir crews. The card records the operational relationship described by the source; it does not prescribe a lighting intervention or claim a quantified effect beyond the cited studies.", fr: "Le chapitre aborde la désynchronisation circadienne et l’éclairage comme des facteurs importants pour le sommeil et la vigilance des astronautes. Il résume de petites études et observations en vol auprès d’équipages de la navette et de Mir. La fiche consigne la relation opérationnelle décrite par la source ; elle ne prescrit aucune intervention d’éclairage et n’affirme aucun effet chiffré au-delà des études citées." },
  "Muestras pequeñas y sistemas de iluminación históricos.": { en: "Small samples and historical lighting systems.", fr: "Petits échantillons et systèmes d’éclairage historiques." },
  "No supongas que los hallazgos se trasladan sin cambios a la iluminación de las naves actuales.": { en: "Do not assume findings transfer unchanged to current spacecraft lighting.", fr: "Ne supposez pas que les résultats s’appliquent tels quels à l’éclairage des vaisseaux actuels." },
  "Factores del entorno que alteran el sueño de los astronautas": { en: "Environmental disruptions to astronaut sleep", fr: "Perturbations environnementales du sommeil des astronautes" },
  "El capítulo reporta datos preliminares, así descritos por sus autores, sobre factores del entorno que pueden alterar el sueño. El resumen citado se refiere a 23 astronautas en nueve vuelos del transbordador. Como el informe califica estos datos de preliminares, la tarjeta conserva esa salvedad y no trata los hallazgos como un estudio causal definitivo.": { en: "The chapter reports preliminary data described by its authors concerning environmental factors that may disrupt sleep. The cited summary refers to 23 astronauts across nine Shuttle flights. Because the report labels these data as preliminary, the card preserves that qualification and does not treat the findings as a definitive causal study.", fr: "Le chapitre rapporte des données préliminaires, qualifiées ainsi par leurs auteurs, sur des facteurs environnementaux susceptibles de perturber le sommeil. Le résumé cité porte sur 23 astronautes répartis sur neuf vols de la navette. Comme le rapport qualifie ces données de préliminaires, la fiche conserve cette réserve et ne traite pas les résultats comme une étude causale définitive." },
  "Datos preliminares.": { en: "Preliminary data.", fr: "Données préliminaires." },
  "No deduzcas causalidad sin conocer el diseño del estudio de base.": { en: "Do not infer causation without the underlying study design.", fr: "Ne déduisez pas de lien de causalité sans connaître le plan de l’étude sous-jacente." },
  "La fuente es histórica.": { en: "The source is historical.", fr: "La source est historique." },
  "Adaptación psicosocial en entornos espaciales aislados y confinados": { en: "Psychosocial adaptation in isolated and confined space environments", fr: "Adaptation psychosociale dans des environnements spatiaux isolés et confinés" },
  "El capítulo de cohesión del equipo analiza experiencias de astronautas y cosmonautas en el espacio junto con evidencia de entornos análogos en tierra. Solo las observaciones de astronautas y cosmonautas pueden entrar en la evidencia central de ASTRA HEALTH, enfocada en astronautas; los hallazgos de análogos deben guardarse aparte como apoyo indirecto. El capítulo subraya que en ese momento la evidencia específica de vuelos espaciales era limitada.": { en: "The team-cohesion chapter discusses astronaut and cosmonaut experiences in space alongside evidence from terrestrial analog environments. Only the astronaut/cosmonaut observations are eligible for ASTRA HEALTH's astronaut-focused core evidence; analog findings must be stored separately as indirect support. The chapter emphasizes that spaceflight-specific evidence was limited at the time.", fr: "Le chapitre sur la cohésion d’équipe aborde les expériences d’astronautes et de cosmonautes dans l’espace ainsi que des données issues d’environnements analogues sur Terre. Seules les observations d’astronautes et de cosmonautes peuvent entrer dans le socle de preuves d’ASTRA HEALTH, centré sur les astronautes ; les résultats des analogues doivent être conservés à part comme soutien indirect. Le chapitre souligne que les preuves propres aux vols spatiaux étaient alors limitées." },
  "No mezcles a los participantes de análogos con las observaciones de astronautas.": { en: "Do not merge analog participants with astronaut observations.", fr: "Ne mélangez pas les participants d’analogues avec les observations d’astronautes." },
  "La fuente no aporta una única estimación cuantitativa estandarizada del efecto.": { en: "The source does not provide a single standardized quantitative effect estimate.", fr: "La source ne fournit pas d’estimation quantitative standardisée unique de l’effet." },
  "Publicado en 2009.": { en: "Published in 2009.", fr: "Publié en 2009." },
  "Cambios cromosómicos medidos en astronautas antes y después del vuelo espacial": { en: "Chromosomal changes measured in astronauts before and after spaceflight", fr: "Changements chromosomiques mesurés chez les astronautes avant et après le vol spatial" },
  "El capítulo 4 reporta hallazgos citogenéticos de muestras de sangre tomadas antes y después del vuelo en 24 astronautas. La figura citada muestra un aumento de los intercambios cromosómicos totales en los 24 astronautas, con translocaciones en 22 de 24 y aberraciones complejas en 17 de 24. Son observaciones de efectos biológicos en astronautas; no son diagnósticos de cáncer ni establecen la incidencia futura de cáncer.": { en: "Chapter 4 reports cytogenetic findings from blood samples collected before and after flight in 24 astronauts. The cited figure reports an increase in total chromosome exchanges in all 24 astronauts, with translocations in 22 of 24 and complex aberrations in 17 of 24. These are biological-effect observations in astronauts; they are not cancer diagnoses and do not establish future cancer incidence.", fr: "Le chapitre 4 rapporte des résultats cytogénétiques issus de prises de sang réalisées avant et après le vol chez 24 astronautes. La figure citée montre une hausse des échanges chromosomiques totaux chez les 24 astronautes, avec des translocations chez 22 sur 24 et des aberrations complexes chez 17 sur 24. Ce sont des observations d’effets biologiques chez les astronautes ; ce ne sont pas des diagnostics de cancer et elles n’établissent pas l’incidence future du cancer." },
  "Los cambios en biomarcadores no equivalen a un diagnóstico de cáncer.": { en: "Biomarker changes do not equal a cancer diagnosis.", fr: "Des changements de biomarqueurs ne valent pas un diagnostic de cancer." },
  "El capítulo no establece resultados de cáncer a largo plazo a partir de esta muestra.": { en: "The chapter does not establish long-term cancer outcomes from this sample.", fr: "Le chapitre n’établit pas de résultats de cancer à long terme à partir de cet échantillon." },
  "El tamaño de la muestra es limitado.": { en: "Sample size is limited.", fr: "La taille de l’échantillon est limitée." },
  "El riesgo de radiación aguda por eventos de partículas solares está modelado para las tripulaciones": { en: "Solar particle event acute-radiation risk is modeled for astronaut crews", fr: "Le risque d’irradiation aiguë lié aux événements de particules solaires est modélisé pour les équipages" },
  "El capítulo 5 evalúa la posibilidad de efectos agudos de la radiación por eventos de partículas solares (SPE) en las tripulaciones mediante escenarios de exposición y modelos de radiación. No reporta casos confirmados de síndrome de radiación aguda en astronautas. La evidencia clínica humana de accidentes en tierra y de irradiación médica se discute en el capítulo, pero queda fuera de esta tarjeta, que solo incluye astronautas.": { en: "Chapter 5 assesses the possibility of acute radiation effects from solar particle events (SPEs) for astronaut crews using exposure scenarios and radiation models. It does not report confirmed astronaut cases of acute radiation syndrome. Human clinical evidence from terrestrial accidents and medical irradiation is discussed in the chapter but is excluded from this astronaut-only card.", fr: "Le chapitre 5 évalue la possibilité d’effets aigus du rayonnement dus aux événements de particules solaires (SPE) pour les équipages, à l’aide de scénarios d’exposition et de modèles de rayonnement. Il ne rapporte aucun cas confirmé de syndrome d’irradiation aiguë chez les astronautes. Les données cliniques humaines issues d’accidents sur Terre et d’irradiations médicales sont discutées dans le chapitre, mais exclues de cette fiche limitée aux astronautes." },
  "Los resultados de un modelo no son observaciones clínicas.": { en: "Model outputs are not clinical observations.", fr: "Les résultats de modèles ne sont pas des observations cliniques." },
  "Los datos de pacientes y sobrevivientes de accidentes en tierra no son datos de astronautas.": { en: "Terrestrial patient and accident-survivor data are not astronaut data.", fr: "Les données de patients et de survivants d’accidents sur Terre ne sont pas des données d’astronautes." },
  "El informe es de 2009.": { en: "The report is from 2009.", fr: "Le rapport date de 2009." },
  "Reportes de astronautas sobre destellos de luz asociados a la radiación": { en: "Astronaut reports of radiation-associated light flashes", fr: "Témoignages d’astronautes sur des éclairs lumineux associés au rayonnement" },
  "El capítulo del SNC reporta que los astronautas observaron destellos de luz durante las misiones Apolo y que el fenómeno también se estudió en Apolo, Skylab, la Mir y la ISS. Estos eventos visuales subjetivos se describen como fosfenos. El capítulo no establece que indiquen lesión cerebral, deterioro cognitivo ni enfermedad neurológica persistente.": { en: "The CNS chapter reports that astronauts observed light flashes during Apollo missions and that studies of the phenomenon were also conducted on Apollo, Skylab, Mir, and the ISS. These subjective visual events are described as phosphenes. The chapter does not establish that they indicate brain injury, cognitive decline, or persistent neurological disease.", fr: "Le chapitre sur le SNC rapporte que des astronautes ont observé des éclairs lumineux lors des missions Apollo et que le phénomène a aussi été étudié sur Apollo, Skylab, Mir et l’ISS. Ces événements visuels subjectifs sont décrits comme des phosphènes. Le chapitre n’établit pas qu’ils traduisent une lésion cérébrale, un déclin cognitif ou une maladie neurologique persistante." },
  "Fenómeno subjetivo.": { en: "Subjective phenomenon.", fr: "Phénomène subjectif." },
  "No establece lesión neurológica ni deterioro funcional persistente.": { en: "Does not establish neurological injury or persistent functional impairment.", fr: "N’établit ni lésion neurologique ni atteinte fonctionnelle persistante." },
  "El mecanismo se discute como una posibilidad, no como una conclusión causal establecida.": { en: "Mechanism is discussed as a possibility, not a settled causal conclusion.", fr: "Le mécanisme est évoqué comme une possibilité, pas comme une conclusion causale établie." },
  "Vacío de evidencia específica en astronautas sobre enfermedad del SNC relacionada con la radiación": { en: "Astronaut-specific evidence gap for radiation-related CNS disease", fr: "Lacune de preuves propres aux astronautes sur les maladies du SNC liées au rayonnement" },
  "El capítulo del SNC afirma que no se habían identificado en astronautas efectos perjudiciales en el SNC por el componente HZE de los rayos cósmicos galácticos, y que con los datos disponibles no se podían hacer proyecciones confiables del riesgo para el SNC. El capítulo se apoya mucho en investigación con animales y células para discutir la plausibilidad biológica; esos estudios quedan fuera de la evidencia central de ASTRA HEALTH, que solo incluye astronautas.": { en: "The CNS chapter states that detrimental CNS effects from the HZE component of galactic cosmic rays had not been identified in astronauts and that reliable CNS risk projections could not be made from the available data. The chapter relies heavily on animal and cellular research to discuss biological plausibility; those studies are excluded from ASTRA HEALTH's astronaut-only evidence core.", fr: "Le chapitre sur le SNC indique qu’aucun effet néfaste sur le SNC dû à la composante HZE du rayonnement cosmique galactique n’avait été identifié chez les astronautes et que les données disponibles ne permettaient pas de projections fiables du risque pour le SNC. Le chapitre s’appuie largement sur des recherches chez l’animal et sur des cellules pour discuter de la plausibilité biologique ; ces études sont exclues du socle de preuves d’ASTRA HEALTH, limité aux astronautes." },
  "Que no se hayan identificado efectos no prueba que no haya riesgo.": { en: "A lack of identified effects is not proof of no risk.", fr: "L’absence d’effets identifiés n’est pas la preuve de l’absence de risque." },
  "Los hallazgos en animales y células no son evidencia directa en astronautas.": { en: "Animal and cell findings are not direct astronaut evidence.", fr: "Les résultats chez l’animal et sur des cellules ne sont pas des preuves directes chez les astronautes." },
  "Evaluación histórica de 2009; hay que revisar la evidencia actual.": { en: "Historical 2009 assessment; current evidence must be checked.", fr: "Évaluation historique de 2009 ; les données actuelles doivent être vérifiées." },
  "Exposición al polvo lunar reportada por los astronautas del Apolo": { en: "Lunar dust exposure reported by Apollo astronauts", fr: "Exposition à la poussière lunaire rapportée par les astronautes d’Apollo" },
  "El capítulo de polvo lunar recoge descripciones de las tripulaciones del Apolo sobre el polvo que entraba al módulo lunar y causaba irritación sensorial, incluidas molestias en ojos, garganta y nariz. También resume el relato de un médico de la tripulación sobre respuestas de tipo alérgico después del vuelo y cambios en los recuentos de eosinófilos y basófilos. Son observaciones históricas de la tripulación y notas clínicas, no un estudio de exposición controlado ni la prueba de un diagnóstico concreto.": { en: "The lunar-dust chapter records Apollo crew descriptions of dust entering the lunar module and causing sensory irritation, including eye, throat, and nasal discomfort. It also summarizes a crew surgeon's account of post-flight allergic-type responses and changes in eosinophil and basophil counts. These are historical crew observations and clinical notes, not a controlled exposure study or proof of a specific diagnosis.", fr: "Le chapitre sur la poussière lunaire consigne les descriptions des équipages d’Apollo sur la poussière entrant dans le module lunaire et provoquant une irritation sensorielle, notamment aux yeux, à la gorge et au nez. Il résume aussi le récit d’un médecin d’équipage sur des réactions de type allergique après le vol et des variations des taux d’éosinophiles et de basophiles. Ce sont des observations historiques de l’équipage et des notes cliniques, pas une étude d’exposition contrôlée ni la preuve d’un diagnostic précis." },
  "Población histórica pequeña y exposiciones breves.": { en: "Small historical mission population and brief exposure durations.", fr: "Petite population historique et durées d’exposition brèves." },
  "No se ha establecido una relación dosis-respuesta definitiva para el polvo lunar en exposiciones prolongadas.": { en: "No definitive long-duration lunar dust dose-response is established.", fr: "Aucune relation dose-réponse définitive n’est établie pour une exposition prolongée à la poussière lunaire." },
  "No deduzcas un diagnóstico confirmado de alergia a partir del relato histórico.": { en: "Do not infer a confirmed allergy diagnosis from the historical account.", fr: "Ne déduisez pas un diagnostic d’allergie confirmé à partir du récit historique." },
  "El guardado de objetos y la accesibilidad del espacio de trabajo en la ISS como factores de seguridad de la tripulación": { en: "ISS stowage and workspace accessibility as crew-safety factors", fr: "Rangement et accessibilité de l’espace de travail sur l’ISS comme facteurs de sécurité de l’équipage" },
  "El capítulo 10 describe preocupaciones operativas de la ISS relacionadas con la acumulación de objetos guardados, rutas de acceso bloqueadas, paneles obstruidos y dificultad para alcanzar el equipo. El capítulo usa comentarios de la tripulación y ejemplos operativos para explicar cómo la distribución del espacio y el guardado pueden afectar la accesibilidad, la eficiencia y la seguridad en emergencias.": { en: "Chapter 10 describes ISS operational concerns related to accumulated stowage, blocked access routes, obstructed panels, and difficulty reaching equipment. The chapter uses crew feedback and operational examples to explain how workspace layout and stowage can affect accessibility, efficiency, and emergency safety.", fr: "Le chapitre 10 décrit des préoccupations opérationnelles de l’ISS liées à l’accumulation d’objets rangés, aux voies d’accès bloquées, aux panneaux obstrués et à la difficulté d’atteindre l’équipement. Le chapitre s’appuie sur les retours de l’équipage et des exemples opérationnels pour expliquer comment l’aménagement de l’espace et le rangement peuvent influer sur l’accessibilité, l’efficacité et la sécurité en cas d’urgence." },
  "El capítulo es una evaluación histórica de las configuraciones y prácticas de la ISS hacia 2009.": { en: "The chapter is a historical assessment of ISS configurations and practices circa 2009.", fr: "Le chapitre est une évaluation historique des configurations et pratiques de l’ISS vers 2009." },
  "No aporta un único resultado de salud cuantificado ni una estimación causal.": { en: "It does not provide a single quantified health outcome or causal estimate.", fr: "Il ne fournit ni résultat de santé chiffré unique ni estimation causale." },
  "Comodidad del traje de EVA y limitaciones de movilidad reportadas en pruebas con personas": { en: "EVA suit comfort and mobility constraints reported in human testing", fr: "Confort de la combinaison d’EVA et contraintes de mobilité rapportés lors d’essais sur l’humain" },
  "El capítulo 10 resume pruebas con personas en las que los participantes reportaron molestias en los trajes espaciales, incluidos hombros, espalda, cuello, rodillas y antebrazos. Las molestias aumentaron durante las pruebas con el traje presurizado. El capítulo relaciona la usabilidad y la comodidad del traje con el rendimiento y la seguridad de la tripulación, aunque las pruebas citadas no equivalen necesariamente a la exposición habitual de un astronauta en vuelo.": { en: "Chapter 10 summarizes human testing in which participants reported discomfort in spacesuits, including the shoulders, back, neck, knees, and lower arms. Discomfort increased during pressurized testing. The chapter links suit usability and comfort to crew performance and safety, while the cited testing is not necessarily equivalent to routine in-flight astronaut exposure.", fr: "Le chapitre 10 résume des essais sur l’humain au cours desquels des participants ont signalé un inconfort dans les combinaisons spatiales, notamment aux épaules, au dos, au cou, aux genoux et aux avant-bras. L’inconfort augmentait lors des essais pressurisés. Le chapitre relie l’ergonomie et le confort de la combinaison aux performances et à la sécurité de l’équipage, même si les essais cités ne sont pas forcément équivalents à l’exposition courante d’un astronaute en vol." },
  "No está establecido que la población sean astronautas en vuelo.": { en: "The population is not established as astronauts in flight.", fr: "Il n’est pas établi que la population soit composée d’astronautes en vol." },
  "Mantén esta tarjeta en una colección indirecta de pruebas con personas, no en la evidencia central de astronautas, salvo que el estudio original confirme que participaron astronautas.": { en: "Keep this card in an indirect human-testing collection, not the astronaut-only core, unless the original study confirms astronaut participants.", fr: "Gardez cette fiche dans une collection indirecte d’essais sur l’humain, et non dans le socle limité aux astronautes, sauf si l’étude originale confirme la participation d’astronautes." },
  "Operaciones de EVA y polvo lunar como vías episódicas de exposición de la tripulación": { en: "EVA operations and lunar dust as episodic crew-exposure pathways", fr: "Opérations d’EVA et poussière lunaire comme voies d’exposition ponctuelles de l’équipage" },
  "El capítulo de polvo lunar identifica varias vías operativas por las que los astronautas podrían entrar en contacto con el polvo: llevarlo al hábitat en trajes y botas después de una EVA, limpiar los trajes entre EVA, cambiar los filtros del control ambiental y permitir que el polvo entre en un vehículo de regreso de la tripulación. Son vías de exposición en escenarios de misión descritas por la NASA, no dosis medidas en una cohorte de tripulantes.": { en: "The lunar-dust chapter identifies several operational pathways by which astronauts could encounter dust: carrying it into a habitat on suits and boots after EVA, cleaning suits between EVAs, changing environmental-control filters, and allowing dust to enter a crew return vehicle. These are mission-scenario exposure pathways described by NASA, not measured dose outcomes in a crew cohort.", fr: "Le chapitre sur la poussière lunaire identifie plusieurs voies opérationnelles par lesquelles les astronautes pourraient être exposés à la poussière : la ramener dans l’habitat sur les combinaisons et les bottes après une EVA, nettoyer les combinaisons entre deux EVA, changer les filtres du contrôle environnemental et laisser la poussière entrer dans un véhicule de retour de l’équipage. Ce sont des voies d’exposition de scénarios de mission décrites par la NASA, pas des doses mesurées dans une cohorte d’équipage." },
  "Las vías potenciales no equivalen a una exposición medida ni a una enfermedad demostrada.": { en: "Potential pathways are not the same as measured exposure or demonstrated disease.", fr: "Des voies potentielles ne sont pas une exposition mesurée ni une maladie démontrée." },
  "La fuente es una evaluación de planificación de misiones de 2009.": { en: "The source is a 2009 mission-planning assessment.", fr: "La source est une évaluation de planification de mission de 2009." },
  "El tiempo de ejercicio como recurso limitado de la misión": { en: "Exercise time as a constrained mission resource", fr: "Le temps d’exercice comme ressource limitée de la mission" },
  "El capítulo de ejercicio describe cómo el ejercicio programado compite con otras actividades dentro de la jornada de la tripulación. Reporta que ninguna evidencia disponible para los autores mostraba que el horario de ejercicio vigente en la ISS hubiera afectado negativamente los objetivos de la misión, aunque identifica un posible riesgo en la asignación del tiempo para misiones de exploración más largas.": { en: "The exercise chapter describes how scheduled exercise competes with other activities within the crew duty day. It reports that no evidence available to the authors showed that the existing ISS exercise schedule had negatively affected mission objectives, while identifying a potential time-allocation risk for longer exploration missions.", fr: "Le chapitre sur l’exercice décrit comment l’exercice programmé entre en concurrence avec d’autres activités dans la journée de travail de l’équipage. Il indique qu’aucune donnée disponible pour les auteurs ne montrait que les horaires d’exercice en vigueur sur l’ISS aient nui aux objectifs de la mission, tout en identifiant un risque potentiel d’allocation du temps pour des missions d’exploration plus longues." },
  "Contexto histórico de horarios y equipo.": { en: "Historical schedule and hardware context.", fr: "Contexte historique d’horaires et d’équipement." },
  "Los impactos en misiones futuras son proyecciones, no resultados observados.": { en: "Future mission impacts are projections, not observed outcomes.", fr: "Les effets sur les missions futures sont des projections, pas des résultats observés." },
  "Sueño corto y menor velocidad de respuesta de la atención sostenida en astronautas de la ISS": { en: "Short sleep and slower vigilant-attention response speed in ISS astronauts", fr: "Sommeil court et vitesse de réponse de l’attention soutenue plus lente chez les astronautes de l’ISS" },
  "En 24 astronautas en misiones de 6 meses en la ISS se aplicó una Prueba Breve de Vigilancia Psicomotora de 3 minutos (PVT-B) con la Reaction Self-Test, junto con el sueño autorreportado. La velocidad de respuesta (el inverso del tiempo de reacción) se asoció con la duración del sueño en 1,774 evaluaciones y fue significativamente más lenta cuando el sueño fue de 6 horas o menos (34.9% de las noches) que cuando fue de más de 6 horas. Los lapsos (tiempo de reacción de 355 ms o más) y las salidas en falso también se asociaron con la duración del sueño, pero las comparaciones por pares no fueron significativas tras corregir por comparaciones múltiples. El artículo no reporta por separado los valores previos al vuelo y en vuelo para lapsos y salidas en falso.": { en: "In 24 astronauts on 6-month ISS missions, a 3-minute Psychomotor Vigilance Test-Brief (PVT-B) was done with the Reaction Self-Test alongside self-reported sleep. Response speed (the reciprocal of reaction time) was associated with sleep duration across 1,774 assessments and was significantly slower when sleep was 6 hours or less (34.9% of nights) than when it was more than 6 hours. Lapses (reaction time of 355 ms or more) and false starts were also associated with sleep duration, but the pairwise comparisons were not significant after correction for multiple comparisons. The article does not report separate pre-flight and in-flight values for lapses and false starts.", fr: "Chez 24 astronautes en mission de 6 mois sur l’ISS, un test bref de vigilance psychomotrice de 3 minutes (PVT-B) a été réalisé avec le Reaction Self-Test, en parallèle d’un sommeil autodéclaré. La vitesse de réponse (l’inverse du temps de réaction) était associée à la durée du sommeil sur 1 774 évaluations et était nettement plus lente quand le sommeil était de 6 heures ou moins (34,9 % des nuits) que lorsqu’il dépassait 6 heures. Les défaillances (temps de réaction de 355 ms ou plus) et les faux départs étaient aussi associés à la durée du sommeil, mais les comparaisons deux à deux n’étaient pas significatives après correction pour comparaisons multiples. L’article ne rapporte pas séparément les valeurs avant et pendant le vol pour les défaillances et les faux départs." },
  "El sueño fue autorreportado y el diseño es observacional, así que no puede demostrar causalidad.": { en: "Sleep was self-reported and the design is observational, so it cannot show causation.", fr: "Le sommeil était autodéclaré et le plan d’étude est observationnel : il ne peut pas démontrer de lien de causalité." },
  "No se pudo evaluar el desajuste circadiano porque faltaban datos continuos de sueño y vigilia.": { en: "Circadian misalignment could not be evaluated because continuous sleep-wake data were lacking.", fr: "Le désalignement circadien n’a pas pu être évalué faute de données continues de veille et de sommeil." },
  "La cafeína pudo influir en la mejora del cuarto trimestre, y el sueño no es el único factor que afecta la atención sostenida.": { en: "Caffeine may have influenced the fourth-quarter improvement, and sleep is not the only factor affecting vigilant attention.", fr: "La caféine a pu influencer l’amélioration du quatrième trimestre, et le sommeil n’est pas le seul facteur qui agit sur l’attention soutenue." },
  "Muestra modesta (19 hombres, 5 mujeres) que no permitió analizar diferencias por sexo.": { en: "Modest sample (19 males, 5 females) that did not allow sex-difference analyses.", fr: "Échantillon modeste (19 hommes, 5 femmes) qui n’a pas permis d’analyser les différences selon le sexe." },
  "El artículo no da un punto de corte de tiempo de reacción ni de número de lapsos que defina un resultado preocupante.": { en: "The article gives no cut-off for reaction time or lapse count that would define a concerning result.", fr: "L’article ne donne aucun seuil de temps de réaction ni de nombre de défaillances définissant un résultat préoccupant." },
};
